void trigger_setup(void) {
  GPIO_InitTypeDef GPIO_InitStruct = {0};
  __HAL_RCC_GPIOA_CLK_ENABLE();

  /*Configure GPIO pin Output Level */
  HAL_GPIO_WritePin(TRIG_OUT_GPIO_Port, TRIG_OUT_Pin, GPIO_PIN_RESET);

  /*Configure GPIO pin : TRIG_OUT_Pin */
  GPIO_InitStruct.Pin = TRIG_OUT_Pin;
  GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_PP;
  GPIO_InitStruct.Pull = GPIO_NOPULL;
  GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
  HAL_GPIO_Init(TRIG_OUT_GPIO_Port, &GPIO_InitStruct);
}
void trigger_high(void) {
  HAL_GPIO_WritePin(TRIG_OUT_GPIO_Port, TRIG_OUT_Pin, SET);
}

void trigger_low(void) {
  HAL_GPIO_WritePin(TRIG_OUT_GPIO_Port, TRIG_OUT_Pin, RESET);
}
char getch(void) {
  uint8_t d;
  while (HAL_UART_Receive(&huart4, &d, 1, 5000) != HAL_OK)
    ;
  return d;
}

void putch(char c) {
  uint8_t d = c;
  HAL_UART_Transmit(&huart4, &d, 1, 5000);
}
